'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];

// Clear guidance for users who open the extracted HTML file directly.
// Basic UI/chat may work from file://, but PWA installation, service workers,
// camera/microphone and secure-context APIs require HTTPS or localhost.
function explainRunMode(){
  const box=document.getElementById('runModeNotice');
  if(!box)return;
  if(location.protocol==='file:'){
    box.hidden=false;
    box.textContent='شما نسخه استخراج‌شده را مستقیماً از حافظه گوشی باز کرده‌اید. این حالت فقط برای بررسی اولیه رابط است؛ نصب برنامه، ذخیره پایدار، میکروفون، دوربین و برخی امکانات مرورگر ممکن است محدود باشند. برای آزمایش کامل، نسخه HTTPS برنامه را در Chrome باز کنید. دکمه‌های اصلی در همین صفحه باید قابل لمس باشند.';
  }
}

// Keep the v0.6 storage key: v0.7 data and the user's existing records remain readable.
const KEY='mr_ai_v06_store', OLD_KEY='mr_ai_v05_store';
function safeGet(key){try{return localStorage.getItem(key);}catch(err){console.warn('Browser storage is unavailable:',err);return null;}}
function safeSet(key,value){try{localStorage.setItem(key,value);return true;}catch(err){console.warn('Browser storage is unavailable:',err);return false;}}
const emptyState=()=>({memory:[],projects:[],messages:[],conversations:[],activeConversationId:null,archivedProjects:[],notifications:[]});
const uniqueRecords=(items)=>{const seen=new Set();return items.filter(item=>{let key;try{key=JSON.stringify(item);}catch{return true;}if(seen.has(key))return false;seen.add(key);return true;});};
function makeStableId(prefix){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;}
function normalizeState(parsed){return {...emptyState(),...parsed,memory:Array.isArray(parsed.memory)?parsed.memory:[],projects:Array.isArray(parsed.projects)?parsed.projects:[],messages:Array.isArray(parsed.messages)?parsed.messages:[],conversations:Array.isArray(parsed.conversations)?parsed.conversations:[],activeConversationId:parsed.activeConversationId||null,archivedProjects:Array.isArray(parsed.archivedProjects)?parsed.archivedProjects:[],notifications:Array.isArray(parsed.notifications)?parsed.notifications:[]};}
function ensureStableIds(normalized){
 // Run only after duplicate records from legacy stores/backups have been merged.
 for(const project of [...normalized.projects,...normalized.archivedProjects]){if(!project.id)project.id=makeStableId('project');if(!Array.isArray(project.tasks))project.tasks=[];for(const task of project.tasks){if(!task.id)task.id=makeStableId('task');if(typeof task.done!=='boolean')task.done=false;if(!['low','medium','high'].includes(task.priority))task.priority='medium';if(typeof task.dueDate!=='string')task.dueDate='';if(typeof task.reminderAt!=='string')task.reminderAt='';if(typeof task.reminderNotifiedAt!=='number')task.reminderNotifiedAt=0;}}
 const allProjects=[...normalized.projects,...normalized.archivedProjects];
 for(const notice of normalized.notifications){if(!notice.id)notice.id=makeStableId('notice');if(typeof notice.readAt!=='number')notice.readAt=0;if(!['low','medium','high'].includes(notice.priority))notice.priority='medium';}
 for(const note of normalized.memory){if(!note.id)note.id=makeStableId('memory');if(!note.projectId&&note.projectName){const matches=allProjects.filter(project=>(project.name||'')===note.projectName);if(matches.length===1)note.projectId=matches[0].id;}}
 return normalized;
}
function migrateConversations(normalized){if(!normalized.conversations.length){const legacy=normalized.messages.slice();const c={id:makeStableId('chat'),title:legacy.find(m=>m.role==='user')?.text?.slice(0,42)||'گفت‌وگوی قبلی',createdAt:Date.now(),updatedAt:Date.now(),messages:legacy};normalized.conversations=[c];normalized.activeConversationId=c.id;}if(!normalized.conversations.some(c=>c.id===normalized.activeConversationId))normalized.activeConversationId=normalized.conversations[0]?.id||null;return normalized;}
function readState(){const candidates=[];for(const key of [KEY,OLD_KEY]){try{const raw=safeGet(key);if(!raw)continue;const parsed=JSON.parse(raw);if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))candidates.push(normalizeState(parsed));}catch(err){console.warn('Stored data could not be read:',err);}}if(!candidates.length)return emptyState();/* Preserve forward-compatible metadata from the newest primary store while merging all record collections. */const merged={...emptyState(),...candidates[0]};for(const item of candidates){for(const key of ['memory','projects','messages','conversations','archivedProjects','notifications'])merged[key]=uniqueRecords([...merged[key],...item[key]]);}return migrateConversations(ensureStableIds(merged));}
function mergeBackup(current,incoming){const merged={...emptyState(),...incoming,...current};for(const key of ['memory','projects','messages','conversations','archivedProjects','notifications'])merged[key]=uniqueRecords([...(Array.isArray(current[key])?current[key]:[]),...(Array.isArray(incoming[key])?incoming[key]:[])]);merged.schemaVersion=14;return migrateConversations(ensureStableIds(merged));}
let state=readState(),mediaKind='image';
function save(){try{if(!safeSet(KEY,JSON.stringify(state)))throw new Error('Storage write failed');return true;}catch(err){alert('ذخیره‌سازی انجام نشد؛ فضای مرورگر ممکن است کافی نباشد. از پشتیبان JSON استفاده کنید.');console.error(err);return false;}}
function commitState(mutator,rerender){const before=JSON.stringify(state);try{mutator();if(!save()){state=JSON.parse(before);if(rerender)rerender();return false;}if(rerender)rerender();return true;}catch(err){state=JSON.parse(before);if(rerender)rerender();console.error('State update failed:',err);alert('تغییر ذخیره نشد؛ اطلاعات قبلی حفظ شدند.');return false;}}
