let currentLang=safeGet('mr_ai_language')||'en';
const t=k=>(translations[currentLang]||translations.en)[k]||translations.en[k]||k;
function applyLanguage(){const rtl=['fa','ar','ur'].includes(currentLang);document.documentElement.lang=currentLang;document.documentElement.dir=rtl?'rtl':'ltr';$$('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));$$('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));$('#languageSelect').value=currentLang;const notice=$('#languageNotice');if(notice){const partial=!translations[currentLang];notice.hidden=!partial;notice.textContent=partial?translations.en.languagePartial:'';}}
languages.forEach(([code,name])=>{const o=document.createElement('option');o.value=code;o.textContent=name;$('#languageSelect').append(o);});
if(!languages.some(x=>x[0]===currentLang)){currentLang='en';safeSet('mr_ai_language','en');}
$('#languageSelect').onchange=e=>{currentLang=e.target.value;safeSet('mr_ai_language',currentLang);applyLanguage();renderMemory();renderProjects();renderNotifications();};
function activeConversation(){return state.conversations.find(c=>c.id===state.activeConversationId)||null;}
function ensureConversation(){let c=activeConversation();if(!c){c={id:makeStableId('chat'),title:'گفت‌وگوی جدید',createdAt:Date.now(),updatedAt:Date.now(),messages:[]};state.conversations.unshift(c);state.activeConversationId=c.id;state.messages=[];}if(!Array.isArray(c.messages))c.messages=[];return c;}
function addMsg(role,text,keep=true){const el=document.createElement('div');el.className='msg '+role;el.textContent=text;$('#messages').append(el);if(keep&&!commitState(()=>{const c=ensureConversation();c.messages.push({role,text,at:Date.now()});c.messages=c.messages.slice(-200);c.updatedAt=Date.now();state.messages=c.messages.slice();if(role==='user'&&(!c.title||c.title==='گفت‌وگوی جدید'||c.title==='New chat'))c.title=text.slice(0,42)+(text.length>42?'…':'');},()=>{renderMessages();renderConversationList();}))return false;$('#messages').scrollTop=$('#messages').scrollHeight;return true;}
function renderMessages(){$('#messages').replaceChildren();const c=ensureConversation();state.messages=c.messages.slice();c.messages.forEach(m=>addMsg(m.role,m.text,false));$('#chatTitle').textContent=c.title||'گفت‌وگو';}
function renderConversationList(){const host=$('#conversationList');if(!host)return;host.replaceChildren();state.conversations.slice().sort((a,b)=>(b.updatedAt||b.createdAt||0)-(a.updatedAt||a.createdAt||0)).forEach(c=>{const row=document.createElement('div');row.className='conversation-row'+(c.id===state.activeConversationId?' active':'');const open=document.createElement('button');open.type='button';open.className='conversation-open';open.textContent=c.title||'گفت‌وگوی بدون عنوان';open.onclick=()=>{commitState(()=>{state.activeConversationId=c.id;state.messages=(c.messages||[]).slice();},()=>{renderMessages();renderConversationList();});};const rename=document.createElement('button');rename.type='button';rename.textContent='✎';rename.setAttribute('aria-label','تغییر نام گفتگو');rename.onclick=()=>{const name=prompt('عنوان جدید گفتگو:',c.title||'');if(name&&name.trim())commitState(()=>{const target=state.conversations.find(x=>x.id===c.id);if(!target)return;target.title=name.trim().slice(0,80);target.updatedAt=Date.now();},()=>{renderMessages();renderConversationList();});};const del=document.createElement('button');del.type='button';del.textContent='×';del.setAttribute('aria-label','حذف گفتگو');del.onclick=()=>{if(!confirm('این گفت‌وگو برای همیشه حذف شود؟'))return;commitState(()=>{state.conversations=state.conversations.filter(x=>x.id!==c.id);if(state.activeConversationId===c.id){state.activeConversationId=state.conversations[0]?.id||null;state.messages=(activeConversation()?.messages||[]).slice();}},()=>{renderMessages();renderConversationList();});};row.append(open,rename,del);host.append(row);});}
function createConversation(){const c={id:makeStableId('chat'),title:'گفت‌وگوی جدید',createdAt:Date.now(),updatedAt:Date.now(),messages:[]};if(commitState(()=>{state.conversations.unshift(c);state.activeConversationId=c.id;state.messages=[];},()=>{renderMessages();renderConversationList();}))$('#userInput').focus();}
function classify(s){const technical=/(معمار[یي]? فنی|هسته مستقل|هسته هوش مصنوعی|معماری نرم.?افزار|technical architecture|software architecture|independent ai core|system architecture)/i.test(s);if(technical)return'technical';if(/برنامه.?ریز|برنامه اجرایی|نقشه راه|مرحله.?به.?مرحله|roadmap|execution plan|project plan|برنامه.*مرحله/i.test(s))return'plan';if(/تحلیل|بررسی|مزایا|محدودیت|ریسک|analy[sz]e|assessment/i.test(s))return'analyze';if(/پرامپت|prompt|تصویر|image|ویدئو|video|موسیقی|music|معمار/i.test(s))return'prompt';return'general';}
function technicalPrompt(s){return `PROMPT — M.R AI INDEPENDENT CORE IMPLEMENTATION\n\nROLE\nAct as a senior software architect and implementation lead experienced in local-first applications, data persistence, modular systems and applied AI.\n\nPROJECT BASELINE\nM.R AI is an existing mobile-first PWA. Existing user data is stored in browser localStorage under mr_ai_v06_store; an older key mr_ai_v05_store may also exist. The current engine is deterministic and rule-based. There is no independently trained language model and no real image, video or audio generation engine connected.\n\nOBJECTIVE\nDesign and implement a staged, testable architecture for an independently owned M.R AI system with durable memory, request analysis, project management and a future path to multimodal creation. Treat the existing application as the baseline; do not replace it with a new unrelated product.\n\nREQUIREMENTS\n1. Inspect the existing source before editing. Identify actual files, data structures, browser APIs and current behavior.\n2. Preserve existing memory, projects, archived projects and conversation history. Keep backward-compatible migration from schema version 7 and existing localStorage keys. Never overwrite user data without a verified backup and explicit confirmation.\n3. Define modular boundaries: interface/localization, conversation orchestration, deterministic task router, memory repository, project/task repository, prompt/workflow builder, import/export, and future model/media adapters.\n4. Separate implemented features from planned features. Do not describe a proposed model, service, database, voice system or media engine as connected or operational.\n5. For persistent memory, specify data schema, CRUD operations, search/retrieval behavior, retention controls, export/import validation, error recovery and backup strategy. Explain the limits of browser storage and propose a migration path to a user-controlled backend only as a future phase.\n6. For request analysis, define intent routing, ambiguity handling, assumptions, constraints, risk identification and acceptance criteria.\n7. For project management, define projects, milestones, tasks, status, timestamps, archive/restore and progress summaries.\n8. For AI independence, distinguish owning the application/orchestration from owning model weights and inference. Compare realistic on-device, self-hosted and hybrid paths without claiming independence that is not achieved.\n9. Keep English as the default language and preserve the configured 39-language selector; ensure RTL handling for Persian, Arabic and Urdu. Do not imply that all 39 interfaces are fully translated unless they are.\n\nIMPLEMENTATION METHOD\nFirst report the repository baseline and risks. Then propose small increments. For every increment provide: files to change, exact code-level work, prerequisites, data migration impact, tests, rollback plan and measurable acceptance criteria. Implement only the first safe increment after the user approves it.\n\nQUALITY AND SAFETY\nUse semantic HTML, accessible controls, safe DOM text insertion, input validation, graceful storage errors and service-worker cache versioning. Never use eval. Avoid destructive migrations. Do not invent test results.\n\nREQUEST TO ADDRESS\n${s}\n\nOUTPUT FORMAT\nA. Current-state findings. B. Target architecture. C. Phased implementation plan. D. Data compatibility and backup plan. E. Test matrix. F. Risks and unresolved decisions. G. First minimal implementation step.`;}
function planResponse(s){return `برنامه اجرایی ساختاریافته\nدرخواست: ${s}\n\nمرحله ۱ — تثبیت وضعیت موجود\n• فایل‌ها، ساختار داده و رفتار فعلی برنامه را ثبت کنید.\n• نسخه پشتیبان JSON را آزمایش و قابلیت بازیابی را روی داده آزمایشی بررسی کنید.\nمعیار پذیرش: حافظه، پروژه‌ها و پیام‌ها پس از بارگذاری مجدد باقی بمانند.\n\nمرحله ۲ — هسته محلی ماژولار\n• مسیریاب درخواست، تحلیل‌گر قانون‌محور، برنامه‌ریز و معمار پرامپت را از هم جدا کنید.\n• برای هر ابزار ورودی، خروجی و خطای مشخص تعریف کنید.\nمعیار پذیرش: درخواست فنی با درخواست تولید تصویر اشتباه گرفته نشود.\n\nمرحله ۳ — حافظه و مدیریت پروژه\n• عملیات ایجاد، ویرایش، جست‌وجو، بایگانی، بازیابی و خروجی JSON را تکمیل کنید.\n• مهاجرت داده نسخه ۷ را بدون حذف فیلدها آزمایش کنید.\nمعیار پذیرش: داده‌های قدیمی بدون تغییر ناخواسته قابل استفاده باشند.\n\nمرحله ۴ — استودیوهای خلاقانه\n• پرامپت‌های تصویر، ویدئو و صدا را با مشخصات تخصصی و کنترل کیفیت جدا کنید.\n• تا زمان اتصال موتور واقعی، وضعیت را «پرامپت‌ساز» اعلام کنید.\nمعیار پذیرش: پرامپت خروجی شامل قالب، مشخصات و موارد ممنوع باشد.\n\nمرحله ۵ — مسیر مدل مستقل و صوت\n• نیازمندی سخت‌افزار، مدل، مجوز، هزینه نگهداری، حریم خصوصی و ارزیابی کیفیت را بررسی کنید.\n• ابتدا نمونه محدود و قابل اندازه‌گیری طراحی کنید؛ اتصال یا خریدی بدون بررسی و تأیید انجام نشود.\n\nترتیب اولویت: حفظ داده ← اصلاح مسیریابی ← حافظه/پروژه ← استودیوها ← مدل و صوت.\nمحدودیت فعلی: این پاسخ با قواعد محلی تولید شده و خروجی مدل زبانی مستقل نیست.`;}
function analyzeResponse(s){return `تحلیل ساختاریافته درخواست\nدرخواست: ${s}\n\n۱) هدف قابل سنجش\nدرخواست را به یک خروجی مشخص و قابل آزمایش تبدیل کنید.\n\n۲) اطلاعات موجود\n• برنامه موجود: PWA موبایل‌محور M.R AI\n• ذخیره‌سازی فعلی: localStorage مرورگر\n• موتور فعلی: قانون‌محور\n• مدل زبانی مستقل و موتورهای واقعی تولید رسانه: هنوز متصل/پیاده‌سازی نشده‌اند.\n\n۳) موارد نامشخص\n• دستگاه و منابع محاسباتی نهایی\n• سطح استقلال مورد انتظار: آفلاین، خودمیزبان یا مالکیت مدل\n• حجم داده و نیازهای همگام‌سازی\n• بودجه و الزامات حریم خصوصی\n\n۴) ریسک‌ها\n• از دست رفتن داده در پاک‌سازی مرورگر\n• بزرگ شدن دامنه پروژه پیش از اثبات نمونه کوچک\n• اشتباه گرفتن رابط کاربری یا پرامپت‌ساز با مدل هوش مصنوعی واقعی\n• هزینه نگهداری مدل و زیرساخت\n\n۵) آزمایش کم‌هزینه\nیک گردش‌کار را انتخاب کنید: ثبت پروژه، افزودن سه وظیفه، بستن و بازکردن برنامه، سپس خروجی و بازیابی نسخه پشتیبان را روی داده آزمایشی بررسی کنید.\n\n۶) معیار موفقیت\nهیچ داده‌ای از بین نرود؛ مسیر درخواست درست تشخیص داده شود؛ خروجی قابل تکرار و محدودیت‌ها شفاف باشند.\n\nاین تحلیل ساختاریافته و قانون‌محور است، نه استدلال یک مدل زبانی مستقل.`;}
function promptResponse(s){return `پرامپت اجرایی آماده تکمیل\n\nنقش: متخصص ارشد حوزه مرتبط با درخواست.\nهدف: ${s}\nزمینه: M.R AI یک PWA موجود با حافظه محلی و موتور قانون‌محور است.\nالزامات: خروجی دقیق، قابل اجرا، مرحله‌ای و سازگار با ساختار موجود؛ تفکیک قابلیت‌های پیاده‌سازی‌شده از پیشنهادها؛ ذکر پیش‌نیازها، فایل‌های درگیر، آزمون‌ها و معیار پذیرش.\nمحدودیت‌ها: سرویس یا مدل خارجی را متصل فرض نکن؛ فایل رسانه‌ای تولیدشده ادعا نکن؛ اطلاعات نامعلوم را جعل نکن؛ پیش از تغییر برگشت‌ناپذیر تأیید بگیر.\nقالب خروجی: هدف، فرض‌ها، مشخصات، مراحل اجرا، کنترل کیفیت، ریسک‌ها و معیار موفقیت.\n\nبرای درخواست‌های معماری فنی، از مسیر «معماری فنی» استفاده کنید تا قالب تخصصی نرم‌افزار تولید شود.`;}
function engine(s){const c=classify(s);if(c==='technical')return technicalPrompt(s);if(c==='plan')return planResponse(s);if(c==='analyze')return analyzeResponse(s);if(c==='prompt')return promptResponse(s);return `درخواست دریافت شد: ${s}\n\nمی‌توانم آن را به تحلیل، برنامه اجرایی، معماری فنی یا پرامپت رسانه‌ای تبدیل کنم. هدف و خروجی مورد انتظار را دقیق‌تر بنویسید.\n\nمحدودیت فعلی: موتور محلی قانون‌محور است و مدل زبانی مستقل متصل نیست.`;}
let lastAssistantReply='';
$('#newConversation').onclick=createConversation;
$('#chatForm').onsubmit=async e=>{e.preventDefault();const s=$('#userInput').value.trim();if(!s)return;if(!addMsg('user',s))return;$('#userInput').value='';const pending=document.createElement('div');pending.className='msg ai';pending.textContent=currentLang==='fa'?'در حال پردازش…':'Working…';$('#messages').append(pending);let answer;try{answer=window.MRAI?.chat?await window.MRAI.chat(s,{language:currentLang,history:(activeConversation()?.messages||[]).slice(-12)}):engine(s);}catch(err){console.warn('Remote model unavailable; using local rule-based engine:',err);const localAnswer=engine(s);answer=currentLang==='fa'?`[پاسخ موتور محلی قانون‌محور؛ مدل زبانی متصل نیست یا در دسترس نیست]\n${localAnswer}`:currentLang==='ar'?`[إجابة المحرك المحلي القائم على القواعد؛ النموذج اللغوي غير متصل أو غير متاح]\n${localAnswer}`:`[Local rule-based response; remote language model is not connected or unavailable]\n${localAnswer}`;}pending.remove();lastAssistantReply=answer;addMsg('ai',answer);};
$$('[data-prompt]').forEach(b=>b.onclick=()=>{$('#userInput').value=b.dataset.prompt;$('#userInput').focus();});
$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.toggle('active',x===b));$$('.view').forEach(x=>x.classList.toggle('active',x.id===b.dataset.view));});
$$('[data-media]').forEach(b=>b.onclick=()=>{mediaKind=b.dataset.media;$('#mediaSubject').focus();$('#mediaSubject').placeholder=({image:'IMAGE: describe the visual concept…',video:'VIDEO: describe scenes, movement and duration…',audio:'AUDIO / MUSIC: describe mood, instruments and structure…'})[mediaKind];});
$('#mediaForm').onsubmit=e=>{e.preventDefault();const subject=$('#mediaSubject').value.trim();if(!subject)return;const style=$('#mediaStyle').value,fmt=$('#mediaFormat').value,details=$('#mediaDetails').value.trim(),v=id=>($(id)?.value||'').trim();const ratio={youtube:'16:9 landscape',shorts:'9:16 vertical',square:'1:1 square'}[fmt];let prompt='';if(mediaKind==='image'){prompt=`IMAGE GENERATION — PROFESSIONAL BRIEF\n\nMAIN CONCEPT: ${subject}\nSTYLE: ${style}\nOUTPUT: ${fmt}, exact ${ratio}\nSUBJECT: ${v('#imageSubjectDetail')||'Use the subject in the concept'}\nCOUNT / ARRANGEMENT: ${v('#imageCount')||'Natural and believable arrangement'}\nENVIRONMENT: ${v('#imageEnvironment')||'A coherent environment relevant to the concept'}\nWATER / MATERIAL: ${v('#imageWater')||'Physically plausible appearance'}\nCAMERA: ${v('#imageCamera')}\nLIGHTING: ${v('#imageLighting')}\nCOMPOSITION: ${v('#imageComposition')}\nQUALITY: ${v('#imageQuality')}\n\nART DIRECTION: Create one coherent image with accurate anatomy and proportions, plausible perspective, physically consistent lighting and reflections, clear subject hierarchy and natural depth. Do not add unrequested text or logos.\n\nNEGATIVE PROMPT: ${v('#imageNegative')||'Deformed anatomy, duplicated subjects, unnatural proportions, unrelated objects, unwanted text, watermark, logo, borders, artifacts, oversharpening.'}\n\nADDITIONAL REQUIREMENTS: ${details||'None supplied'}\n\nQUALITY CHECKS: Verify exact aspect ratio, subject count, anatomy, edges, reflections, focus, color consistency and absence of unwanted text/artifacts.`;}else if(mediaKind==='video'){prompt=`VIDEO PRODUCTION BRIEF\nCONCEPT: ${subject}\nSTYLE: ${style}\nFORMAT: ${fmt} (${ratio})\nDURATION: ${details||'Specify target duration before production'}\nSHOT PLAN: Define opening, main action, transition and ending. For every shot specify duration, framing, camera movement, subject action, environment and lighting.\nCONTINUITY: Maintain subject identity, scale, direction, environment, lighting and color across shots. Motion must be physically plausible.\nAUDIO: Specify ambience, effects, music and dialogue separately; avoid clipping and abrupt level changes.\nNEGATIVE CONSTRAINTS: No flicker, morphing, duplicated subjects, unstable geometry, random text, watermarks or unrelated elements.\nQUALITY CHECKS: Verify timing, frame continuity, aspect ratio, motion stability, audio sync and final export settings.`;}else{prompt=`AUDIO / MUSIC PRODUCTION BRIEF\nCONCEPT: ${subject}\nSTYLE / MOOD: ${style}\nTARGET: ${fmt}\nDURATION / STRUCTURE: ${details||'Specify duration; define intro, development, climax and ending.'}\nSOUND DESIGN: Specify instrumentation, timbre, tempo, rhythm, dynamics, spatial character and transitions. Keep the arrangement coherent and leave appropriate headroom.\nVOCAL / SPOKEN CONTENT: Include only if explicitly requested; define language, delivery and intelligibility.\nNEGATIVE CONSTRAINTS: No clipping, distortion, unwanted noise, abrupt cuts, unintended vocals or unrelated sounds.\nQUALITY CHECKS: Check loudness consistency, clean transitions, timing, frequency balance and export format.`;}$('#mediaPrompt').textContent=prompt;};
$('#copyMediaPrompt').onclick=async()=>{try{await navigator.clipboard.writeText($('#mediaPrompt').textContent);$('#copyMediaPrompt').textContent=t('copy')+' ✓';setTimeout(()=>$('#copyMediaPrompt').textContent=t('copy'),1400);}catch{alert('کپی خودکار در دسترس نیست؛ متن را انتخاب و کپی کنید.');}};
function normalizeMemoryQuery(value){return String(value??'').normalize('NFKC').toLocaleLowerCase().trim();}
function memoryMatches(note,query){if(!query)return true;return normalizeMemoryQuery(`${note?.title||''} ${note?.body||''} ${note?.category||''} ${note?.projectName||''}`).includes(query);}
function memoryCategoryMatches(note,category){return !category||normalizeMemoryQuery(note?.category||'')===normalizeMemoryQuery(category);}
function refreshMemoryProjectOptions(selected=''){
 const select=$('#memoryProjectInput'); if(!select)return;
 select.replaceChildren(); const none=document.createElement('option');none.value='';none.textContent=t('noProject');select.append(none);
 [...state.projects,...state.archivedProjects].forEach(project=>{const option=document.createElement('option');option.value=project.id;option.textContent=(project.name||'Project')+(state.archivedProjects.includes(project)?' (archived)':'');select.append(option);});
 select.value=selected;
}
function renderMemory(){
 const box=$('#memoryList');box.replaceChildren();const query=normalizeMemoryQuery($('#memorySearch')?.value||'');
 const categoryFilter=$('#memoryCategoryFilter');const selectedCategory=categoryFilter?.value||'';
 if(categoryFilter){const keep=selectedCategory;const categories=[...new Set(state.memory.map(n=>(n.category||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));categoryFilter.replaceChildren();const all=document.createElement('option');all.value='';all.textContent=currentLang==='fa'?'همه دسته‌ها':currentLang==='ar'?'كل الفئات':'All categories';categoryFilter.append(all);categories.forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;categoryFilter.append(option);});categoryFilter.value=categories.includes(keep)?keep:'';}
 const matches=state.memory.map((note,index)=>({note,index})).filter(item=>memoryMatches(item.note,query)&&memoryCategoryMatches(item.note,selectedCategory));
 const summary=$('#memorySearchSummary');if(summary)summary.textContent=`${t('memoryResults')}: ${matches.length} / ${state.memory.length}`;
 if(!matches.length&&query){const empty=document.createElement('p');empty.className='muted';empty.textContent=t('memoryNoResults');box.append(empty);return;}
 matches.forEach(({note,index})=>{
  const d=document.createElement('div');d.className='entry memory-entry';const title=document.createElement('b'),body=document.createElement('p'),meta=document.createElement('p'),editBtn=document.createElement('button'),deleteBtn=document.createElement('button');
  title.textContent=note.title||'Note';body.textContent=note.body||'';meta.className='muted';
  const linked=[...state.projects,...state.archivedProjects].find(project=>project.id===note.projectId);
  const projectName=linked?.name||note.projectName||'';meta.textContent=`${t('category')}: ${note.category||t('uncategorized')} · ${t('linkedProject')}: ${projectName||t('noProject')}`;
  const editor=document.createElement('form');editor.className='memory-inline-editor';editor.hidden=true;
  const titleInput=document.createElement('input');titleInput.maxLength=160;titleInput.required=true;titleInput.value=note.title||'';titleInput.setAttribute('aria-label','Note title');
  const bodyInput=document.createElement('textarea');bodyInput.maxLength=12000;bodyInput.required=true;bodyInput.value=note.body||'';bodyInput.setAttribute('aria-label','Note text');
  const categoryInput=document.createElement('input');categoryInput.maxLength=80;categoryInput.value=note.category||'';categoryInput.placeholder=t('category');categoryInput.setAttribute('aria-label','Category');
  const projectSelect=document.createElement('select');const noProject=document.createElement('option');noProject.value='';noProject.textContent=t('noProject');projectSelect.append(noProject);
  [...state.projects,...state.archivedProjects].forEach(project=>{const option=document.createElement('option');option.value=project.id;option.textContent=(project.name||'Project')+(state.archivedProjects.includes(project)?' (archived)':'');projectSelect.append(option);});
  projectSelect.value=note.projectId||'';
  const saveBtn=document.createElement('button');saveBtn.type='submit';saveBtn.className='primary';saveBtn.textContent=currentLang==='fa'?'ذخیره تغییرات':currentLang==='ar'?'حفظ التغييرات':'Save changes';
  const cancelBtn=document.createElement('button');cancelBtn.type='button';cancelBtn.textContent=currentLang==='fa'?'لغو':currentLang==='ar'?'إلغاء':'Cancel';cancelBtn.onclick=()=>{editor.hidden=true;editBtn.focus();};
  editor.append(titleInput,bodyInput,categoryInput,projectSelect,saveBtn,cancelBtn);
  editBtn.textContent=t('edit');editBtn.onclick=()=>{editor.hidden=!editor.hidden;if(!editor.hidden)titleInput.focus();};
  editor.onsubmit=e=>{e.preventDefault();const nextTitle=titleInput.value.trim(),nextBody=bodyInput.value.trim(),projectId=projectSelect.value;const project=[...state.projects,...state.archivedProjects].find(item=>item.id===projectId);if(!nextTitle||!nextBody){alert('Title and note text cannot be empty.');return;}commitState(()=>{const target=state.memory.find(item=>item.id===note.id);if(!target)return;target.title=nextTitle;target.body=nextBody;target.category=categoryInput.value.trim();target.projectId=projectId;target.projectName=project?.name||'';target.updatedAt=Date.now();},renderMemory);};
  deleteBtn.textContent=t('delete');deleteBtn.onclick=()=>{if(confirm(t('confirmDeleteNote')))commitState(()=>state.memory.splice(state.memory.findIndex(item=>item.id===note.id),1),renderMemory);};
  d.append(title,body,meta,editBtn,deleteBtn,editor);box.append(d);
 });
}
$('#memorySearch').addEventListener('input',renderMemory);
$('#memoryCategoryFilter').addEventListener('change',renderMemory);
$('#memoryForm').onsubmit=e=>{e.preventDefault();const title=$('#memoryTitleInput').value.trim(),body=$('#memoryBodyInput').value.trim(),category=$('#memoryCategoryInput').value.trim(),projectId=$('#memoryProjectInput').value,project=[...state.projects,...state.archivedProjects].find(item=>item.id===projectId);if(!title||!body)return;if(commitState(()=>state.memory.unshift({id:makeStableId('memory'),title,body,category,projectId,projectName:project?.name||'',at:Date.now(),updatedAt:Date.now()}),renderMemory)){e.target.reset();refreshMemoryProjectOptions();}};
function projectMatches(project,query){const q=String(query||'').normalize('NFKC').toLocaleLowerCase().trim();if(!q)return true;return `${project.name||''} ${project.desc||''}`.normalize('NFKC').toLocaleLowerCase().includes(q);}
function projectStatistics(project,memory){const tasks=Array.isArray(project.tasks)?project.tasks:[];return {notes:memory.filter(note=>note.projectId===project.id).length,total:tasks.length,done:tasks.filter(task=>task.done).length};}
function renameProjectLinks(projectId,newName,memory){for(const note of memory){if(note.projectId===projectId)note.projectName=newName;}}
function localDateKey(date=new Date()){const y=date.getFullYear(),m=String(date.getMonth()+1).padStart(2,'0'),d=String(date.getDate()).padStart(2,'0');return `${y}-${m}-${d}`;}
function isTaskOverdue(task,today=localDateKey()){return !!task.dueDate&&!task.done&&task.dueDate<today;}
function filterProjectTasks(tasks,filter,today=localDateKey()){return (Array.isArray(tasks)?tasks:[]).filter(task=>filter==='overdue'?isTaskOverdue(task,today):filter==='pending'?!task.done:filter==='done'?task.done:true);}
function taskStatistics(tasks,today=localDateKey()){const list=Array.isArray(tasks)?tasks:[];return {total:list.length,done:list.filter(x=>x.done).length,overdue:list.filter(x=>isTaskOverdue(x,today)).length};}
function dueReminderTasks(projects,now=Date.now()){const due=[];for(const project of Array.isArray(projects)?projects:[])for(const task of Array.isArray(project.tasks)?project.tasks:[]){const at=task.reminderAt?Date.parse(task.reminderAt):NaN;if(Number.isFinite(at)&&at<=now&&!task.done&&!task.reminderNotifiedAt)due.push({project,task});}return due;}
function createReminderNotification(project,task,now=Date.now()){return {id:makeStableId('notice'),type:'task-reminder',projectId:project.id||'',taskId:task.id||'',title:project.name||'Project',body:task.title||'Task reminder',priority:['low','medium','high'].includes(task.priority)?task.priority:'medium',createdAt:now,readAt:0,reminderAt:task.reminderAt||''};}
function notificationMatches(item,filter='all',priority='all'){return (filter!=='unread'||!item.readAt)&&(priority==='all'||item.priority===priority);}
function renderNotifications(){const box=$('#notificationList');if(!box)return;box.replaceChildren();const filter=$('#notificationFilter')?.value||'all',priority=$('#notificationPriorityFilter')?.value||'all';const items=(state.notifications||[]).filter(n=>notificationMatches(n,filter,priority)).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0));if(!items.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=t('noNotifications');box.append(empty);return;}for(const item of items){const row=document.createElement('article');row.className=`notification-item priority-${item.priority}${item.readAt?' is-read':''}`;const title=document.createElement('b');title.textContent=item.title||'M.R AI';const body=document.createElement('p');body.textContent=item.body||'';const meta=document.createElement('small');meta.textContent=`${t('notificationPriority')}: ${item.priority} · ${new Date(item.createdAt||Date.now()).toLocaleString()}`;row.append(title,body,meta);if(!item.readAt){const read=document.createElement('button');read.type='button';read.className='ghost';read.textContent=t('markRead');read.onclick=()=>commitState(()=>{const target=state.notifications.find(n=>n.id===item.id);if(target)target.readAt=Date.now();},renderAllNotifications);row.append(read);}box.append(row);}}
function renderAllNotifications(){renderNotifications();}
function renderProjectList(items,target,archived=false){const box=$(target);box.replaceChildren();const query=$('#projectSearch')?.value||'';const visible=items.filter(project=>projectMatches(project,query));if(!visible.length){if(query){const empty=document.createElement('p');empty.className='muted';empty.textContent=t('noProjectResults');box.append(empty);}return;}visible.forEach(p=>{if(!Array.isArray(p.tasks))p.tasks=[];const d=document.createElement('div');d.className='entry';const title=document.createElement('b'),desc=document.createElement('p'),archive=document.createElement('button'),del=document.createElement('button');title.textContent=p.name||'Project';desc.textContent=p.desc||'';archive.textContent=archived?t('restoreProject'):t('archive');del.textContent=t('delete');archive.onclick=()=>commitState(()=>{const index=items.findIndex(x=>x.id===p.id);if(index<0)return;if(archived){state.projects.unshift({...p,archived:false});state.archivedProjects.splice(index,1);}else{state.archivedProjects.unshift({...p,archived:true});state.projects.splice(index,1);}},renderProjects);del.onclick=()=>{if(confirm(t('confirmDeleteProject')))commitState(()=>{const index=items.findIndex(x=>x.id===p.id);if(index>=0)items.splice(index,1);},renderProjects);};d.append(title,desc);
const stats=projectStatistics(p,state.memory),summary=document.createElement('p');summary.className='muted';summary.textContent=t('projectStats').replace('{notes}',stats.notes).replace('{done}',stats.done).replace('{total}',stats.total);d.append(summary);
const editDetails=document.createElement('details'),editSummary=document.createElement('summary');editSummary.textContent=t('editProject');editDetails.append(editSummary);const editForm=document.createElement('form');editForm.className='memory-inline-editor';const nameInput=document.createElement('input');nameInput.value=p.name||'';nameInput.maxLength=160;nameInput.required=true;nameInput.setAttribute('aria-label','Project name');const descInput=document.createElement('textarea');descInput.value=p.desc||'';descInput.maxLength=4000;descInput.setAttribute('aria-label','Project description');const saveButton=document.createElement('button');saveButton.type='submit';saveButton.className='primary';saveButton.textContent=t('saveProject');editForm.append(nameInput,descInput,saveButton);editForm.onsubmit=e=>{e.preventDefault();const nextName=nameInput.value.trim();if(!nextName)return;commitState(()=>{p.name=nextName;p.desc=descInput.value.trim();p.updatedAt=Date.now();renameProjectLinks(p.id,nextName,state.memory);},renderProjects);};editDetails.append(editForm);d.append(editDetails);
const taskStats=taskStatistics(p.tasks),taskTitle=document.createElement('h4');taskTitle.textContent=`${t('taskCount')} (${taskStats.done}/${taskStats.total} • ${t('overdue')}: ${taskStats.overdue})`;d.append(taskTitle);const taskFilter=document.createElement('select');taskFilter.className='task-filter';taskFilter.setAttribute('aria-label',t('filterTasks'));[['all',t('allTasks')],['pending',t('pending')],['done',t('done')],['overdue',t('overdueOnly')]].forEach(([value,label])=>{const o=document.createElement('option');o.value=value;o.textContent=label;taskFilter.append(o);});d.append(taskFilter);const taskBox=document.createElement('div');d.append(taskBox);function drawTasks(){taskBox.replaceChildren();filterProjectTasks(p.tasks,taskFilter.value).forEach(task=>{const row=document.createElement('div');row.className='task-row';const label=document.createElement('span');label.textContent=task.title;label.className=task.done?'task-done':'';const meta=document.createElement('small');const priorityLabel=task.priority==='high'?t('highPriority'):task.priority==='low'?t('lowPriority'):t('mediumPriority');meta.textContent=`${t('priority')}: ${priorityLabel}${task.dueDate?' · '+t('dueDate')+': '+task.dueDate:''}${isTaskOverdue(task)?' · '+t('overdue'):''}${task.reminderAt?' · '+t('reminderAt')+': '+task.reminderAt.replace('T',' '):''}`;if(isTaskOverdue(task))meta.className='task-overdue';const toggle=document.createElement('button');toggle.textContent=task.done?t('pending'):t('done');toggle.onclick=()=>commitState(()=>{task.done=!task.done;},renderProjects);const remove=document.createElement('button');remove.textContent=t('delete');remove.onclick=()=>commitState(()=>{const idx=p.tasks.findIndex(x=>x.id===task.id);if(idx>=0)p.tasks.splice(idx,1);},renderProjects);row.append(label,meta,toggle,remove);taskBox.append(row);});}taskFilter.onchange=drawTasks;drawTasks();if(!archived){const form=document.createElement('form');form.className='task-form';const input=document.createElement('input');input.placeholder=t('taskPlaceholder');input.maxLength=180;input.required=true;const priority=document.createElement('select');priority.setAttribute('aria-label',t('priority'));[['low',t('lowPriority')],['medium',t('mediumPriority')],['high',t('highPriority')]].forEach(([value,label])=>{const o=document.createElement('option');o.value=value;o.textContent=label;priority.append(o);});const due=document.createElement('input');due.type='date';due.setAttribute('aria-label',t('dueDate'));const reminder=document.createElement('input');reminder.type='datetime-local';reminder.setAttribute('aria-label',t('reminderAt'));const add=document.createElement('button');add.className='primary';add.textContent=t('addTask');form.append(input,priority,due,reminder,add);form.onsubmit=e=>{e.preventDefault();const value=input.value.trim();if(!value)return;commitState(()=>{if(!Array.isArray(p.tasks))p.tasks=[];p.tasks.push({id:makeStableId('task'),title:value,done:false,priority:priority.value,dueDate:due.value,reminderAt:reminder.value,reminderNotifiedAt:0,createdAt:Date.now()});},renderProjects);};d.append(form);}d.append(archive,del);box.append(d);});}
$('#projectSearch').addEventListener('input',renderProjects);
$('#projectForm').onsubmit=e=>{e.preventDefault();const name=$('#projectName').value.trim();if(!name)return;if(commitState(()=>state.projects.unshift({id:makeStableId('project'),name,desc:$('#projectDesc').value.trim(),at:Date.now(),updatedAt:Date.now(),archived:false,tasks:[]}),renderProjects))e.target.reset();};
function exportBackup(){const payload={...state,exportedAt:new Date().toISOString(),schemaVersion:14,sourceSchemaVersion:Number.isInteger(state.schemaVersion)?state.schemaVersion:7};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MR-AI-backup-v0109.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$$('[data-tool]').forEach(b=>b.onclick=()=>{const k=b.dataset.tool;if(k==='export'){exportBackup();return;}const starters={plan:'برای این پروژه یک برنامه اجرایی مرحله‌به‌مرحله با فایل‌های درگیر و معیار پذیرش تهیه کن: ',prompt:'برای این درخواست یک پرامپت کامل و آماده کپی تولید کن: ',analyze:'این درخواست را از نظر هدف، فرض‌ها، ریسک‌ها و آزمایش کم‌هزینه تحلیل کن: '};$('#userInput').value=starters[k]||'';$('.tab[data-view="chat"]').click();$('#userInput').focus();});
$('#importFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const previousState=state;let previousStorage=null;let hadPreviousStorage=false;try{const incomingRaw=JSON.parse(await file.text());if(!incomingRaw||typeof incomingRaw!=='object'||!Array.isArray(incomingRaw.memory)||!Array.isArray(incomingRaw.projects))throw new Error('ساختار حافظه یا پروژه‌ها معتبر نیست.');const incoming=normalizeState(incomingRaw);const next=mergeBackup(state,incoming);const added={};for(const key of ['memory','projects','messages','conversations','archivedProjects','notifications'])added[key]=next[key].length-state[key].length;if(!confirm(`Backup validated. Import will MERGE records without replacing current data. New items: ${added.memory} memories, ${added.projects} projects, ${added.messages} messages, ${added.archivedProjects} archived projects, ${added.notifications} notifications. Continue?`))return;try{previousStorage=localStorage.getItem(KEY);hadPreviousStorage=previousStorage!==null;}catch(storageReadError){throw new Error('Cannot safely read the current browser backup; import was cancelled without changing data.');}state=next;if(!save())throw new Error('Import could not be saved. Existing browser data was restored.');renderMemory();renderProjects();renderMessages();renderConversationList();renderNotifications();alert('Backup merged successfully. Existing records were retained.');}catch(err){state=previousState;try{if(hadPreviousStorage)localStorage.setItem(KEY,previousStorage);else localStorage.removeItem(KEY);}catch(rollbackError){console.error('Could not restore previous browser storage:',rollbackError);}alert(`Import failed: ${err.message||'Invalid JSON backup.'}`);}finally{e.target.value='';}};

// Browser-native two-way voice beta. Availability and language quality depend on the device/browser.
const speechLocales={en:'en-US',fa:'fa-IR',ar:'ar-SA',de:'de-DE',fr:'fr-FR',es:'es-ES',pt:'pt-PT',ru:'ru-RU',zh:'zh-CN',hi:'hi-IN',tr:'tr-TR',it:'it-IT',ja:'ja-JP',ko:'ko-KR',id:'id-ID',bn:'bn-BD',ur:'ur-PK',sw:'sw-KE',vi:'vi-VN',th:'th-TH',nl:'nl-NL',pl:'pl-PL',uk:'uk-UA',ro:'ro-RO',el:'el-GR',sv:'sv-SE',no:'nb-NO',da:'da-DK',fi:'fi-FI',cs:'cs-CZ',hu:'hu-HU',ms:'ms-MY',ta:'ta-IN',te:'te-IN',mr:'mr-IN',gu:'gu-IN',pa:'pa-IN',am:'am-ET',ha:'ha-NG'};
const voiceStatus=$('#voiceStatus');
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
let recognition=null;
function setVoiceStatus(message){if(voiceStatus)voiceStatus.textContent=message;}
if(!Recognition){$('#voiceInput').disabled=true;setVoiceStatus('Speech recognition is not supported by this browser.');}
else{
 recognition=new Recognition();recognition.lang=speechLocales[currentLang]||'en-US';recognition.interimResults=true;recognition.continuous=false;
 recognition.onstart=()=>setVoiceStatus('Listening… speak now.');
 recognition.onresult=event=>{let finalText='',partial='';for(let i=event.resultIndex;i<event.results.length;i++){const transcript=event.results[i][0].transcript;if(event.results[i].isFinal)finalText+=transcript;else partial+=transcript;}const recognized=(finalText||partial).trim();if(recognized)$('#userInput').value=recognized;};
 recognition.onerror=event=>setVoiceStatus(`Voice input error: ${event.error}`);
 recognition.onend=()=>{setVoiceStatus($('#userInput').value.trim()?'Recognition finished. Review or edit the text, then press Send to continue.':'No speech was recognized. Try again or type your request.');$('#userInput').focus();};
 $('#voiceInput').onclick=()=>{try{recognition.lang=speechLocales[currentLang]||'en-US';recognition.start();}catch(err){setVoiceStatus('Voice input could not start. If it is already listening, wait until it stops before trying again.');}};
}
$('#languageSelect').addEventListener('change',()=>{if(recognition)recognition.lang=speechLocales[currentLang]||'en-US';});
$('#speakLast').onclick=()=>{if(!('speechSynthesis'in window)){setVoiceStatus('Speech output is not supported by this browser.');return;}if(!lastAssistantReply){setVoiceStatus('There is no answer to read yet.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(lastAssistantReply);utterance.lang=speechLocales[currentLang]||'en-US';utterance.onerror=()=>setVoiceStatus('Speech output failed on this device.');utterance.onstart=()=>setVoiceStatus('Reading the latest answer aloud…');utterance.onend=()=>setVoiceStatus('Finished reading the answer.');speechSynthesis.speak(utterance);};
$('#stopSpeech').onclick=()=>{if('speechSynthesis'in window)speechSynthesis.cancel();setVoiceStatus('Speech stopped.');};

// Reminder checks run only while this page is active; browsers may suspend background tabs.
const notificationStatus=$('#notificationStatus');
function setNotificationStatus(message){if(notificationStatus)notificationStatus.textContent=message;}
$('#enableNotifications').onclick=async()=>{if(!('Notification'in window)){setNotificationStatus('Notifications are not supported by this browser.');return;}try{const permission=await Notification.requestPermission();setNotificationStatus(permission==='granted'?'Notifications enabled.':`Notification permission: ${permission}.`);}catch(err){setNotificationStatus('Could not request notification permission.');}};
function checkTaskReminders(){const due=dueReminderTasks(state.projects);if(!due.length)return;let changed=false;for(const {project,task} of due){const notice=createReminderNotification(project,task,Date.now());state.notifications.unshift(notice);let delivered=false;if('Notification'in window&&Notification.permission==='granted'){try{new Notification(`M.R AI • ${project.name||'Project'}`,{body:`Reminder: ${task.title}`,tag:`mrai-${task.id}`});delivered=true;}catch(err){console.warn('Reminder notification failed:',err);}}task.reminderNotifiedAt=Date.now();changed=true;}if(changed){save();renderNotifications();}}
checkTaskReminders();window.setInterval(checkTaskReminders,30000);
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Service worker registration failed',err)));

// Android-friendly PWA installation. The browser decides whether installation is available.
let deferredInstallPrompt=null;
const installAppButton=document.getElementById('installAppButton');
const mobileInstallNotice=document.getElementById('mobileInstallNotice');
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;if(installAppButton){installAppButton.hidden=false;installAppButton.textContent=currentLang==='fa'?'نصب برنامه':'Install app';}});
installAppButton?.addEventListener('click',async()=>{if(!deferredInstallPrompt){if(mobileInstallNotice)mobileInstallNotice.textContent=currentLang==='fa'?'در Chrome اندروید، منوی سه‌نقطه را باز کنید و «Install app» یا «Add to Home screen» را بزنید.':'In Android Chrome, open the three-dot menu and choose “Install app” or “Add to Home screen”.';return;}deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;if(choice?.outcome==='accepted'&&mobileInstallNotice)mobileInstallNotice.textContent=currentLang==='fa'?'درخواست نصب پذیرفته شد. برنامه را از صفحه اصلی گوشی باز کنید.':'Install accepted. Open M.R AI from your home screen.';deferredInstallPrompt=null;installAppButton.hidden=true;});
window.addEventListener('appinstalled',()=>{if(installAppButton)installAppButton.hidden=true;if(mobileInstallNotice)mobileInstallNotice.textContent=currentLang==='fa'?'M.R AI روی گوشی نصب شد.':'M.R AI is installed on this device.';});

